"""Configuration loading helpers."""

from pathlib import Path


def config_path(name: str) -> Path:
    return Path("configs") / name


def load_retry_policy() -> dict:
    return {"initial_delay_seconds": 30, "max_attempts": 5}


def load_feature_flags() -> dict:
    """Load feature flags from configs/feature_flags.yaml.

    Returns an empty dict when the file is missing or unreadable.
    """
    path = config_path("feature_flags.yaml")
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return {}

    flags: dict = {}
    section: dict | None = None
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("-"):
            continue
        if ":" not in line:
            continue
        key, _, value = line.partition(":")
        key = key.strip()
        value = value.strip()
        if not key:
            continue
        if value == "":
            section = {}
            flags[key] = section
        else:
            target = section if section is not None else flags
            target[key] = _parse_scalar(value)
    return flags


def _parse_scalar(value: str) -> object:
    if value in ("true", "True"):
        return True
    if value in ("false", "False"):
        return False
    if value in ("null", "~"):
        return None
    if value.startswith('"') and value.endswith('"'):
        return value[1:-1]
    if value.startswith("'") and value.endswith("'"):
        return value[1:-1]
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass
    return value
